widgets_values:
{
  "整体风格": "电影写实，秋日皇家猎场氛围，黄叶与金甲交织的暖色基调，辅以烛火昏黄与深夜墨蓝的冷暗对比，大气磅礴与危机暗涌并置，铺垫-递进-高潮-回落节奏完整，以金色阳光和滴血黑血作为视觉母题复现",
  "角色档案": [
    "永安帝·李晟，男，赤金盘龙冠，明黄窄袖龙袍，胸口五爪金龙，黑色束腰革带，脚蹬乌金战靴，配装：穿云弓（金漆弓身，玄铁弓弦，龙纹雕饰）常悬马侧",
    "太子·李怀瑾，男，白玉冠，玄色暗纹锦袍，腰悬蟠龙玉佩，脚蹬黑缎朝靴，配装：蟠龙玉佩（青白玉，龙纹浮雕，系于腰间革带）",
    "三皇子·李怀瑜，男，银冠束发，靛蓝劲装，拇指戴碧玉扳指，脚蹬鹿皮靴，配装：碧玉扳指（翠绿色，光润剔透，套于右手拇指）",
    "九公主·李长乐，女，双鬟髻，银质蝴蝶发梳，绯红骑装，腰系药囊，脚蹬云纹绣鞋，配装：药囊（灰蓝色粗布，系于腰间，内装银针与药粉）",
    "太医令·赵守正，男，深青色官袍，头戴乌纱幞头，蓄山羊胡，脚蹬黑布靴，配装：诊脉枕（深蓝色锦缎，内充荞麦，随身携带）",
    "内侍·黄门，男，浅蓝色圆领宦袍，头戴无翅纱帽，手持拂尘，脚蹬皂靴"
  ],
  "道具档案": [
    "穿云弓：金漆弓身，玄铁弓弦，弓臂雕有蟠龙戏珠纹，弦上系赤红丝穗，长约四尺，于秋日阳光下泛冷冽金属光泽",
    "白鹿：通体雪白，鹿角如巨大珊瑚分叉，皮毛在逆光中镀上一层金边，眼瞳黑亮，立于空地中央孤石前",
    "药渣堆与千日醉毒引：深褐色碎草药，杂有十余粒极小深褐色颗粒，颗粒表面覆有细密蜡衣，于烛火下微微反光，遇热蜡衣溶化",
    "黑血：太医令口中喷出之暗黑色血块，黏稠，落地后迅速渗入青砖缝隙，边缘有细密气泡"
  ],
  "场景档案": [
    "猎场高台：秋日午时，金黄色阳光铺满高台。地面为浅黄石板，四围立赤色旌旗。核心地标为高台中央的金漆龙椅，椅背雕五爪金龙。台下为黄土地猎场，远处连绵金色营帐与红叶林，天际线处青山如黛",
    "围猎区密林：秋日午后，阳光穿透黄叶与红叶，斑驳洒落。地面铺满干枯落叶与松针，马蹄踏过发出沙沙声。林木高耸，树冠遮蔽天光，形成明暗交替的林间光影。核心地标为一条林间土路，两侧灌木丛生",
    "林中空地：秋日近黄昏，西斜阳光以逆光角度射入，将空地照得金黄。四周林木环绕形成半圆形包围，地面为青苔与短草，中央一处石堆。核心地标为空地中央的孤石，白鹿驻足于石前",
    "行宫寝室内：室内昏黄，烛火摇动。地面为青砖，四壁为白墙，悬挂数幅山水画。核心地标为龙床，床架紫檀木雕龙纹，层层明黄锦帐垂落。床前设一张紫檀案几，上有青瓷药碗与铜烛台。窗户紧闭，厚锦帘掩住外部光线",
    "行宫偏殿：深夜，孤灯一盏。地面为青石板，四壁为灰砖墙，墙角堆叠卷宗与药箱。核心地标为一张黑漆木案，案上摊开药渣堆。窗外夜色墨黑，远处猎场大营灯火隐约"
  ],
  "分镜序列": [
    {
      "编号": 1,
      "标题": "猎场高台-秋猎大典",
      "时间段": [
        "0-5s，航拍大远景缓慢下移。秋季金色阳光铺满猎场，旌旗赤色如海，万马奔腾。永安帝·李晟端坐高台金漆龙椅，太子·李怀瑾侍立左侧，三皇子·李怀瑜在右侧，九公主·李长乐立于父皇身后，远景黄叶林与营帐连绵。音效：号角齐鸣，骏马嘶鸣，群臣山呼万岁",
        "5-10s，中景，过肩镜头从永安帝·李晟背后俯视台下。永安帝·李晟起身，双手张开，明黄龙袍在风中猎猎。内侍·黄门高喊。永安帝·李晟说：\"今日秋猎，朕要亲手猎一头猛虎回来！取朕的穿云弓！\"（口音：京腔，语速：正常，情绪：激昂豪迈）。音效：风声，号角回声",
        "10-15s，中近景，太子·李怀瑾上前一步，面朝永安帝·李晟，眉头微蹙，玄色锦袍袖口紧握。太子·李怀瑾说：\"父皇，您近来龙体欠安。不如就在台上观猎，由儿臣代劳。\"（口音：京腔，语速：缓，情绪：克制担忧）。音效：衣料摩擦声，远处马蹄声"
      ]
    },
    {
      "编号": 2,
      "标题": "猎场高台-父子交锋",
      "时间段": [
        "0-5s，近景，永安帝·李晟侧脸，金色阳光从右上方斜切，冠上赤金龙纹反光。永安帝·李晟笑着摇头，伸手拍太子·李怀瑾肩膀。永安帝·李晟说：\"怀瑾，你这孩子，才多大年纪，怎么比你母后还啰嗦？\"（口音：京腔，语速：正常，情绪：慈爱调侃）。音效：铠甲轻碰声，笑声",
        "5-10s，中景，三皇子·李怀瑜斜倚栏杆，右手转动碧玉扳指，靛蓝劲装随意敞开领口。三皇子·李怀瑜说：\"就是！父皇老当益壮，大哥您别扫兴。去年您夺了秋猎头筹，今年怎么也让我试试吧？\"（口音：京腔，语速：轻快，情绪：嬉笑不羁）。音效：玉扳指旋转摩擦声，笑声",
        "10-14s，全景，永安帝·李晟大笑指怀瑜，太子·李怀瑾微微侧头看向怀瑜，九公主·李长乐站在后方低头掩嘴轻笑，银质蝴蝶发梳微颤。永安帝·李晟说：\"你？就你那三脚猫的箭法，可别又把箭射到树上去！\"（口音：京腔，语速：正常，情绪：爽朗大笑）。音效：人群笑声，风拂旌旗声"
      ]
    },
    {
      "编号": 3,
      "标题": "猎场高台-兄妹斗嘴",
      "时间段": [
        "0-5s，中近景，九公主·李长乐抬头，双鬟髻微晃，银质蝴蝶发梳反光。九公主·李长乐轻声说：\"三哥去年射了三只兔子、两只野鸡——外加迷路三次。儿臣都记着呢。\"（口音：京腔，语速：正常，情绪：俏皮调侃）。音效：衣料摩挲声，远处号角余韵",
        "5-10s，全景，永安帝·李晟转身大步走下高台，袍摆翻飞。太子·李怀瑾快步跟上。永安帝·李晟边走边说：\"好了好了！都别贫了。备马！怀瑾随朕下场，怀瑜，你护着长乐，别让她乱跑！\"（口音：京腔，语速：快，情绪：愉悦干脆）。音效：靴踏石阶声，马匹嘶鸣",
        "10-15s，中景，三皇子·李怀瑜抱拳笑着应声，九公主·李长乐低头嘟囔。三皇子·李怀瑜说：\"儿臣领命！不过父皇，长乐可比我会骑马，谁护着谁还不一定呢。\"（口音：京腔，语速：快，情绪：嬉笑）。九公主·李长乐小声嘟囔：\"谁要他护着……\"（口音：京腔，语速：缓，情绪：微嗔）。音效：马鞍响动，马蹄轻踏"
      ]
    },
    {
      "编号": 4,
      "标题": "猎场高台-太子叮嘱",
      "时间段": [
        "0-5s，近景，太子·李怀瑾走过三皇子·李怀瑜身边，压低声音，玄色锦袍袖口掠过怀瑜手臂。太子·李怀瑾说：\"怀瑜，盯紧长乐。今日林中人多，别出什么岔子。\"（口音：京腔，语速：缓，情绪：严肃低沉）。音效：衣料摩擦，皮靴踏地",
        "5-10s，近景，三皇子·李怀瑜收笑容，正色点头，碧玉扳指在阳光下微闪。三皇子·李怀瑜说：\"大哥放心。\"（口音：京腔，语速：缓，情绪：郑重）。音效：扳指轻磕木栏",
        "10-14s，过肩镜头从太子·李怀瑾背后看永安帝·李晟背影，太子·李怀瑾袍袖中的手缓缓握紧，指节发白，随即松开。太子·李怀瑾快步跟上，玉冠在光中泛温润白。音效：风声，马蹄声渐近"
      ]
    },
    {
      "编号": 5,
      "标题": "围猎区密林-驰猎",
      "时间段": [
        "0-5s，中景，林间土路上马蹄声疾。永安帝·李晟一骑当先，明黄龙袍在红叶与黄叶间格外醒目，阳光透过树叶形成斑驳光点。太子·李怀瑾紧随其后，始终落后三个马身。三皇子·李怀瑜与九公主·李长乐并行在后。音效：马蹄踏碎落叶声，马具晃动声，鸟鸣",
        "5-10s，中景，三皇子·李怀瑜策马追上前，侧头朝太子·李怀瑾喊话。三皇子·李怀瑜说：\"大哥！父皇今天这架势，怕是要把林子里所有猎物都包圆了！您可追紧点儿！\"（口音：京腔，语速：快，情绪：兴奋）。太子·李怀瑾没有回头，声音平稳：\"你护着长乐，不用管我。\"（口音：京腔，语速：正常，情绪：沉静）。音效：马蹄声，风声",
        "10-15s，中景，九公主·李长乐在后面喊，三皇子·李怀瑜勒马放慢回头笑。九公主·李长乐说：\"三哥！你慢点！我的马胆小，你一惊一乍的它会害怕！\"（口音：京腔，语速：快，情绪：嗔怪）。三皇子·李怀瑜说：\"什么马胆小，我看是你胆小吧！当年是谁从假山上摔下来，把父皇吓得——\"（口音：京腔，语速：快，情绪：嬉笑调侃）。音效：马蹄声，风声，树叶沙沙"
      ]
    },
    {
      "编号": 6,
      "标题": "围猎区密林-温馨打断",
      "时间段": [
        "0-5s，中近景，九公主·李长乐脸红，扬起马鞭作势要打，绯红骑装在阳光中泛暖。九公主·李长乐急急打断：\"三哥！不许说！\"（口音：京腔，语速：快，情绪：恼羞）。音效：马鞭破空声，风声",
        "5-10s，中景，三皇子·李怀瑜大笑策马躲开，靛蓝劲装下摆翻飞，阳光洒在两人身上。九公主·李长乐抿嘴催马追去，银质蝴蝶发梳在光中闪烁。音效：马蹄声，笑声，树叶摩擦声",
        "10-14s，远景，林间阳光从红叶间倾泻，成束光柱中两人策马追逐，远处永安帝·李晟与太子·李怀瑾的背影渐小。旁白：\"那一刻，他们只是一家人。\"音效：马蹄声渐远，鸟鸣，风过林梢"
      ]
    },
    {
      "编号": 7,
      "标题": "林中空地-白鹿现身",
      "时间段": [
        "0-5s，中景，西斜阳光逆光射入空地，白鹿从林中跃出，浑身雪白，巨大鹿角如珊瑚分叉，立于中央孤石前，逆光给鹿身镀金边。三皇子·李怀瑜压低声音难掩兴奋：\"白鹿……大哥，是白鹿！\"（口音：京腔，语速：缓，情绪：震惊兴奋）。音效：鹿蹄轻踏碎石，树叶沙沙",
        "5-10s，过肩镜头从永安帝·李晟背后看白鹿。永安帝·李晟缓缓抬起穿云弓，金色弓身在逆光中闪耀。永安帝·李晟低沉兴奋：\"天佑我天晟。今日，朕便射这头白鹿，为秋猎祭旗。\"（口音：京腔，语速：缓，情绪：庄重豪迈）。音效：弓弦轻响，风穿过鹿角声",
        "10-15s，特写，永安帝·李晟张弓搭箭，弓弦拉满。特写——额头上渗出细密汗珠，握弓的手微微颤抖，金色龙袍袖口被风吹动。太子·李怀瑾在旁看得清楚，眉头猛地皱紧。音效：弓弦绷紧的吱嘎声，心跳声（贴录）"
      ]
    },
    {
      "编号": 8,
      "标题": "林中空地-坠马惊变",
      "时间段": [
        "0-5s，近景，太子·李怀瑾不自觉地上前半步，声音发紧：\"父皇——\"（口音：京腔，语速：缓，情绪：惊惶急迫）。音效：马蹄不安踏地，弓弦颤音",
        "5-10s，特写，永安帝·李晟咬牙低喝，箭矢离弦。白鹿受惊跃起，箭矢擦着鹿角飞过射入树干。永安帝·李晟身体猛然僵住，穿云弓滑落，整个人向马下栽去。音效：弓弦释放轰鸣声，箭矢破空声，白鹿跃起蹄声",
        "10-14s，中景，太子·李怀瑾飞扑上前，在落马半空中接住永安帝·李晟，自己重重摔在地上，背脊撞击地面。太子·李怀瑾抱紧父亲，声音撕裂：\"父皇——！！！\"音效：沉闷撞击声，铠甲碰撞声，太子·李怀瑾闷哼"
      ]
    },
    {
      "编号": 9,
      "标题": "林中空地-兄妹驰援",
      "时间段": [
        "0-5s，中景，三皇子·李怀瑜和九公主·李长乐同时勒马冲来。三皇子·李怀瑜翻身下马，脸色刷白。三皇子·李怀瑜说：\"父皇！父皇！大哥，父皇怎么了？！\"（口音：京腔，语速：快，情绪：惊恐焦急）。音效：马蹄急停声，衣料摩擦声",
        "5-10s，中近景，九公主·李长乐跌跌撞撞跑来，扑到永安帝·李晟身旁，手颤抖着探脉搏，强作镇定。九公主·李长乐说：\"不要动他！三哥，不要动父皇！让父皇平躺！\"（口音：京腔，语速：快，情绪：强撑镇定）。音效：心跳声（贴录），落叶被踩碎声",
        "10-15s，中景，太子·李怀瑾抱着永安帝·李晟，声音沙哑抬头朝侍卫喊。太子·李怀瑾说：\"传太医！快传太医！\"（口音：京腔，语速：快，情绪：沙哑撕裂）。周围骑手惊恐驻足，远处号角声仍在回荡。音效：号角回声，马蹄杂沓，人群骚动"
      ]
    },
    {
      "编号": 10,
      "标题": "行宫寝室内-太医束手",
      "时间段": [
        "0-5s，全景，行宫寝室内昏黄烛光摇动，永安帝·李晟躺于龙床，素白寝衣，散发无冠，面色灰败，呼吸微弱。太子·李怀瑾跪在床前，玉冠已重新扶正但眼眶泛红。九公主·李长乐跪握父亲手。三皇子·李怀瑜背靠门框，低着头，指节发白。音效：烛火噼啪，呼吸声（微弱）",
        "5-10s，近景，太医令·赵守正跪伏于地，深青色官袍，额头触地，浑身颤抖。太医令·赵守正说：\"禀太子殿下……陛下脉象紊乱，似有邪风入体。臣等……臣等无能，束手无策……\"（口音：京腔，语速：缓，情绪：恐慌颤抖）。音效：官袍摩擦青砖声，太子·李怀瑾拳头握紧声",
        "10-15s，中近景，太子·李怀瑾没有回头，声音低沉，极力压制情绪：\"赵太医，你在太医院四十年，服侍过两朝天子。今日，我只问你一句——父皇，到底能不能醒。\"（口音：京腔，语速：缓，情绪：压制怒火）。音效：衣料摩擦，烛火跳动"
      ]
    },
    {
